<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) - Piet Mondrian</title>
<meta name="description" content="Piet Mondrian, Composition with Red, Blue and Yellow, 1930. De Stijl, Neoplasticism, Kunsthaus Zurich.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;800;900&display=swap" rel="stylesheet">
<style>
:root{--red:#d40920;--blue:#1356a2;--yellow:#fac901;--white:#f6f4ec;--black:#111;--line:clamp(6px,1vw,12px)}
*{box-sizing:border-box;margin:0}
body{background:var(--black);color:var(--black);font:400 clamp(1rem,1.2vw,1.2rem)/1.55 Archivo,"Helvetica Neue",Arial,sans-serif}
main{display:grid;gap:var(--line);grid-template-columns:repeat(12,1fr);max-width:1400px;margin:0 auto;padding:var(--line);background:var(--black)}
main>*{background:var(--white);padding:clamp(1rem,3vw,2.5rem)}
.title{grid-column:1/8;grid-row:1/3;display:flex;flex-direction:column;justify-content:flex-end;min-height:70vh}
.eyebrow{font-weight:800;text-transform:uppercase;letter-spacing:.14em;font-size:.8rem}
h1{font-weight:900;font-size:clamp(2.2rem,6vw,5.5rem);line-height:.95;text-transform:uppercase;margin:1rem 0}
.lede{max-width:34ch;font-size:1.15em}
.red{grid-column:8/13;grid-row:1/3;background:var(--red);color:#fff;display:flex;flex-direction:column;justify-content:flex-end}
.red .big{font-weight:900;font-size:clamp(3.5rem,11vw,9rem);line-height:.9}
.red small{font-weight:800;text-transform:uppercase;letter-spacing:.12em}
.fact{grid-column:span 4}
.fact h2,.why h2,.rules h2{font-weight:900;text-transform:uppercase;font-size:1.1rem;letter-spacing:.08em;margin-bottom:.6rem}
.fact p{font-size:1.1em}
.blue{background:var(--blue)!important;color:#fff}
.yellow{background:var(--yellow)!important}
.rules{grid-column:1/9}
.rules ul{list-style:none;padding:0;display:flex;flex-wrap:wrap;gap:.6rem;margin-top:1rem}
.rules li{border:var(--line) solid var(--black);padding:.3rem .8rem;font-weight:800;text-transform:uppercase;font-size:.85rem}
.sw{display:inline-block;width:.9em;height:.9em;border:2px solid var(--black);vertical-align:-.1em;margin-right:.4em}
.art{grid-column:9/13;display:grid;place-items:center}
.art svg{width:100%;height:auto;max-width:360px;border:var(--line) solid var(--black)}
.why{grid-column:1/13;display:grid;grid-template-columns:1fr 2fr;gap:2rem;align-items:center}
.why p{font-size:clamp(1.2rem,2.4vw,2rem);font-weight:800;line-height:1.25}
.cta{grid-column:1/13;background:var(--yellow)!important;display:flex;flex-wrap:wrap;gap:1.5rem;align-items:center;justify-content:space-between}
.cta a{background:var(--black);color:#fff;padding:1rem 1.6rem;font-weight:800;text-transform:uppercase;letter-spacing:.08em;text-decoration:none;border:3px solid var(--black)}
.cta a:hover,.cta a:focus-visible{background:var(--red);outline:3px solid var(--black);outline-offset:3px}
.cta p{font-weight:800;font-size:1.3em;max-width:28ch}
footer{grid-column:1/13;font-size:.85rem}
@media(max-width:760px){.title,.red,.fact,.rules,.art,.why{grid-column:1/13;grid-row:auto}.title{min-height:50vh}.why{grid-template-columns:1fr}}
@media(prefers-reduced-motion:no-preference){.red{animation:in .8s ease-out both}@keyframes in{from{transform:translateX(30px);opacity:0}}}
</style>
</head>
<body>
